/**
 * Arabic dictionary (right-to-left).
 *
 * Intentionally a Partial: a key not listed here renders its German text, never
 * a raw key. The coverage test (`ar.test.ts`) nevertheless requires every German
 * key to be present, so it fails until the translations are imported.
 *
 * Owner's decisions of 27.11.2026:
 *   1. Arabic is a full UI language, written right to left.
 *   2. Numbers, money and dates keep the German format with Latin digits
 *      (`41,47 €`, `27.11.2026`). Arabic-Indic digits are refused by the tests
 *      and by `scripts/i18n-merge.mjs`.
 *   3. German domain terms (Stundennachweis, Fahrtenbuch, Abrechnung, Beleg,
 *      Werkstatt, Monatsplanung, Lohnart, Bundesland, Gehaltsquittung …) appear
 *      as Arabic with the German in brackets at the FIRST mention in a string:
 *      "كشف الساعات (Stundennachweis)". Later mentions in the same string use the
 *      Arabic alone.
 *
 * Placeholders `{name}` are kept exactly as in German. `.other` plural strings
 * must read correctly for any count (see translatePlural in index.ts).
 *
 * Generate this file with `node scripts/i18n-merge.mjs --ar-import <dir>`;
 * do not edit it by hand in parallel.
 */
