  'admin.settings.tab.flags': 'أعلام الميزات',
  'admin.flags.hint': 'مفتاح واحد لكل علم تعرفه نسخة البرنامج هذه. العلم المطفأ هنا مطفأ، وهو الحالة نفسها لعلم غير مخزَّن. تلتقط الجلسات المفتوحة التغيير عند تسجيل الدخول التالي، أو بعد خمس دقائق على الأكثر من عودة النافذة إلى النشاط.',
