  'admin.flags.unknownDesc': 'لا تقرأ نسخة البرنامج هذه هذا العلم في أي مكان. المفتاح لا يغيّر شيئًا هنا، والقيمة المخزَّنة معروضة فقط.',
  'admin.flags.unknownNote': 'العلم المعلَّم بـ “غير معروف” مخزَّن في قاعدة البيانات لكن نسخة البرنامج هذه لا تقرؤه في أي مكان، فقد جاء من نسخة أقدم أو كُتب مباشرة عبر SQL. يمكن إزالته، أما الأعلام الجديدة فلا تنشأ إلا من نسخة برنامج تقرؤها.',
  'admin.flags.flag.travelEstimator': 'فحص زمن الرحلة في تحليل الرحلات',
  'admin.flags.flag.travelEstimator.desc': 'مفعّل: يحوّل تحليل الرحلات العناوين إلى نقاط، بدءًا بمخزن عناوين الشركة ثم مرمّز العناوين في هذه المنظومة، ويفحص بها مسافة الرحلة ومدتها. معطّل: لا يُطلب شيء من أحد ويبقى كل فحص “غير قابل للفحص” كما كان قبل هذه الميزة. أول تشغيل فعلي هو أيضًا تشغيل القبول: يُطلب كل عنوان مرة واحدة ويُحفظ بصورة دائمة. يبقى نحو ثلث الرحلات “غير قابل للفحص” بصورة دائمة لأن الملف لا يحتوي رقم مبنى لأحد الطرفين، وهذا ليس خللًا بل هو محتوى الملف. يتطلب حاوية التوجيه وبوابة المرمّز ومخزن العناوين، وإن غاب أحدها يبقى “غير قابل للفحص”.',
  'admin.team.title': 'الفريق',
  'admin.team.subtitle': 'حسابات ذات صلاحيات على المنصة',
  'admin.team.noAccessBody': 'لا يدير الفريق إلا مالكو المنصة.',
  'admin.team.roleNote': 'يحدّد الدور ما يحق للحساب فعله على المنصة. ويمكن تغييره لاحقًا لعضو نشط عبر “تغيير الدور”، مع بقاء العضوية وتاريخ الانضمام والملاحظة. يستطيع الدعم والقراءة فقط قراءة أدلة جميع العملاء (المركبات والسائقين والمستخدمين مع بريدهم الإلكتروني)، أما بقية بيانات العميل فلا تُقرأ إلا داخل جلسة مفتوحة. وحده المالك يدير الفريق ويعتمد الشركات أو يوقفها ويغيّر الإعدادات ويقرأ سجل التدقيق.',
