  'admin.team.grantedBy.unrecordedNote': 'تعني “غير مسجَّل” تحت “منح الصلاحية” أن هذه العضوية أُنشئت قبل أن تسجّل المنصة من يمنح الوصول، وهكذا نشأ أول المالكين، أو أُنشئت خارج هذه الصفحة، لذلك لا يوجد اسم مسجَّل لها. أما من يُضاف عبر هذه الصفحة فيحمل دائمًا الحساب الذي منحه الصلاحية.',
