  'admin.team.role.hint.support': 'يقرأ أدلة جميع العملاء. يمكنه فتح جلسة دعم وقراءة بيانات ومستخدمي شركة واحدة بالضبط وتعديلها داخلها، ويُسجَّل كل تعديل. لا تسوية ولا اعتماد للشركات ولا إيقافها.',
  'admin.team.role.hint.billing': 'التسوية والأسعار والرموز والفواتير. يقرأ البيانات الأساسية للشركات دون بيانات العملاء التشغيلية، ولا يمكنه فتح أي جلسة.',
